/* Reference-theme views. The application owns state, authentication and API calls. */
function refHeader(active='landing') {
  return `<header class="ref-site-header">${brand()}<nav aria-label="Main navigation">${[['site-solutions','Solutions'],['site-ai','AI Workspace'],['site-industries','Industries'],['site-resources','Resources'],['site-about','About']].map(([id,t])=>`<a href="#${id}" ${active===id?'aria-current="page"':''}>${t}</a>`).join('')}</nav><div class="ref-site-actions"><a href="#site-resources" aria-label="Search resources">${icon('search')}</a><a class="ref-glass-button" href="${appUser?'#home':'#login'}">${appUser?'Workspace':'Sign in'}</a><a class="ref-lime-button" href="${appUser?'#home':'#login'}">Get Started ${icon('arrow')}</a></div></header>`;
}
function refLanding() {
  return `<div class="ref-landing">${refHeader()}<main><section class="ref-landing-hero"><span class="ref-kicker">AI FOR A BRIGHTER TOMORROW</span><h1>A Smarter<br><span>Connected</span><br><em>Pakistan</em></h1><h2>Secure. Intelligent. Built for what’s next.</h2><p>CloudCore AI brings people, information and ideas together — helping organizations work smarter, faster and more securely.</p><div class="ref-hero-actions"><a class="ref-lime-button" href="${appUser?'#home':'#login'}">Explore AI Workspace ${icon('arrow')}</a><a class="ref-watch" href="#site-ai"><span>${icon('play')}</span>Discover CloudCore AI</a></div></section><section class="ref-service-strip">${[['chat','AI Workspace','Chat, meet and get insights — all in one place.','site-ai'],['shield','Enterprise Security','Your data. Your priority. Built for trust at scale.','site-about'],['file','Document Intelligence','Understand, compare and extract insights instantly.','site-solutions'],['chart','Real Impact','Turn information into your next business decision.','site-industries']].map(([i,t,d,r])=>`<a href="#${r}"><span class="ref-dark-icon">${icon(i)}</span><div><b>${t}</b><p>${d}</p></div><span class="ref-round-arrow">${icon('arrow')}</span></a>`).join('')}</section><footer class="ref-landing-footer"><span>A product of<br><b>PTCL Smart Cloud</b></span><span>Grounded answers</span><span>Meeting intelligence</span><span>Document & image insight</span><a href="#site-solutions">Scroll to explore ${icon('arrow')}</a></footer></main></div>`;
}
function refSidebar(r) {
  const name=appUser?.displayName||'CloudCore user';
  return `<aside class="sidebar ref-sidebar"><div class="ref-sidebar-inner">${brand()}<nav aria-label="Product navigation">${[...navs.filter(n=>n[0]!=='history'),['settings','settings','Settings']].map(([id,i,t])=>`<a href="#${id}" class="${r===id?'selected':''}" ${r===id?'aria-current="page"':''}>${icon(i)}<span>${id==='meetings'?'Meeting Intelligence':id==='documents'?'Document Insights':t}</span></a>`).join('')}<a class="ref-history-link ${r==='history'?'selected':''}" href="#history">${icon('history')}<span>Chat History</span></a></nav><div class="ref-sidebar-bottom"><a class="ref-future-card" href="#landing"><span>Hello<br>to the Future</span><i>${icon('arrow')}</i></a><button class="ref-sidebar-user" data-action="profile"><span class="avatar">${esc(name.charAt(0))}</span><span><b>${esc(name)}</b><small>${esc(appUser?.role||'Workspace member')}</small></span><span>⌄</span></button></div></div></aside>`;
}
function refWorkspace(r) {
  if(!navs.some(n=>n[0]===r)&&r!=='settings')r='home';
  const body=r==='home'?refHome():r==='meetings'?refMeetings():r==='documents'?refDocuments():r==='images'?refImages():r==='history'?refHistory():r==='settings'?refSettings():refAssistant();
  return `<div class="workspace ref-workspace ${r}-workspace ${r==='assistant'&&!messages.length?'ref-assistant-empty':''}">${refSidebar(r)}<div class="workspace-body"><header class="workspace-header"><button class="mobile-menu icon-button" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><form class="global-search" id="search-form">${icon('search')}<input aria-label="Search products, guides, solutions" placeholder="Search across your workspace, documents, meetings, images..."></form><button class="icon-button notification" data-action="notifications" aria-label="Notifications">${icon('bell')}<i></i></button>${r==='assistant'?'<button class="ref-glass-button ref-new-chat" data-action="new-chat">'+icon('spark')+' New Chat</button>':''}</header><main class="workspace-main">${body}</main></div></div><input hidden type="file" id="document-input" accept=".pdf,.docx,.pptx,.xlsx,.txt,.md"><input hidden type="file" id="image-input" accept="image/png,image/jpeg,image/webp"><dialog id="dialog"><button class="dialog-close icon-button" data-action="close-dialog" aria-label="Close">${icon('close')}</button><div id="dialog-content"></div></dialog>`;
}
function refHome() {
  const name=(appUser?.displayName||'there').split(' ')[0];
  const recent=chats.slice(0,3);
  return `<section class="ref-home-heading"><div><h1>Good morning, ${esc(name)}</h1><p>Let’s make today productive.</p></div><time>${new Date().toLocaleDateString('en-GB',{weekday:'long',timeZone:'Asia/Karachi'})}<br>${new Date().toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Karachi'})}</time></section><section class="ref-home-hero"><span class="ref-kicker">CLOUDCORE AI WORKSPACE</span><h2>Your AI Workspace<br><span>for a more connected tomorrow.</span></h2><p>One intelligent workspace. Four powerful capabilities.<br>Built for Pakistan. Designed for what’s next.</p><a class="ref-lime-button" href="#assistant">Explore AI Workspace ${icon('arrow')}</a></section><section class="home-cards ref-home-cards">${[['chat','Chat with CloudCore','Get answers, draft content, analyze information and more.','Research · Summarize · Plan','assistant'],['video','Meeting Intelligence','Turn discussions into actionable insights.','Transcribe · Summarize · Act','meetings'],['file','Document Insights','Understand and extract key information.','Compare · Extract · Analyze','documents'],['image','Image Analysis','Analyze images, diagrams and visual content.','Identify · Extract text · Explain','images']].map(([i,t,d,tags,r],n)=>`<a class="ref-capability capability-${n}" href="#${r}"><span class="feature-icon">${icon(i)}</span><h2>${t}</h2><p>${d}</p><div><small>${tags}</small><span class="ref-round-arrow">${icon('arrow')}</span></div></a>`).join('')}</section><div class="ref-home-lists"><section class="panel"><div class="panel-heading">${icon('clock')}<h2>Recent Activity</h2><a href="#history">View all →</a></div>${recent.length?recent.map(c=>`<button class="ref-activity-row" data-action="open-chat" data-id="${esc(c.id)}"><span class="mini-icon">${icon('chat')}</span><span><b>${esc(c.title)}</b><small>Conversation · ${new Date(c.updated).toLocaleDateString()}</small></span><span>Continue →</span></button>`).join(''):'<div class="ref-empty-inline">Your recent conversations will appear here.<a href="#assistant">Start a conversation →</a></div>'}</section><section class="panel"><div class="panel-heading">${icon('folder')}<h2>Continue where you left off</h2><a href="#documents">View all →</a></div>${docFile?`<button class="ref-activity-row" data-action="ref-document-route"><span class="mini-icon">${icon('file')}</span><span><b>${esc(docFile.name)}</b><small>Document · selected on this device</small></span><span>Continue →</span></button>`:'<div class="ref-empty-inline">Bring your documents and meetings into one workspace.<a href="#meetings">Open Meeting Intelligence →</a></div>'}</section></div>`;
}
function refAssistant() {
  if(messages.length)return `<section class="ref-conversation"><div class="ref-conversation-heading"><h1>AI Assistant</h1><button class="outline" data-action="new-chat">${icon('plus')} New Chat</button></div><div class="messages">${messages.map((m,i)=>`<article class="message ${m.role==='user'?'user':'assistant'}"><span class="message-avatar">${m.role==='user'?esc((appUser?.displayName||'U')[0]):mark()}</span><div class="chat-text" ${m.streaming?'id="active-assistant-stream-bubble"':''}>${m.role==='user'?esc(m.content):renderMarkdown(m.content)}${m.streaming?'<span class="typing-cursor"></span>':''}</div></article>`).join('')}</div>${composer('assistant')}</section>`;
  const items=[['file','Summarize<br>this document','Get key points, action items and insights instantly.','documents'],['video','Draft a meeting<br>summary','Turn discussions into clear, actionable notes.','meetings'],['chart','Compare<br>strategies','Analyze options and find the best path forward.','assistant'],['image','Analyze<br>this image','Understand and extract key information.','images']];
  return `<section class="ref-assistant-stage"><div class="ref-assistant-options">${items.map(([i,t,d,r],n)=>`<a class="ref-assistant-option option-${n}" href="#${r}" ${n===2?'data-action="suggestion" data-prompt="Compare cloud solutions"':''}><span class="ref-dark-icon">${icon(i)}</span><h2>${t}</h2><p>${d}</p><i class="ref-round-arrow">${icon('arrow')}</i></a>`).join('')}</div><div class="ref-assistant-name"><h1>CloudCore AI</h1><p>Your intelligent partner at PTCL Smart Cloud.</p></div></section><div class="ref-assistant-composer">${composer('assistant')}</div><nav class="ref-assistant-shortcuts" aria-label="Assistant tools"><a href="#documents">${icon('file')}Work with Documents</a><a href="#images">${icon('image')}Analyze Images</a><a href="#meetings">${icon('video')}Plan Meetings</a><a href="#history">${icon('bulb')}Get Insights</a></nav>`;
}
function assistant(){return refAssistant();}
function history(){return refHistory();}
function refHistory() {
  const items=chats.filter(c=>!historySearch||c.title.toLowerCase().includes(historySearch.toLowerCase()));
  return `${title('YOUR WORKSPACE','Chat History','Revisit your conversations and continue your work.')}<section class="panel ref-history-panel"><label class="ref-search">${icon('search')}<input id="history-search" type="search" placeholder="Search conversations..." value="${esc(historySearch)}" aria-label="Search conversations"></label>${items.length?items.map(c=>`<article class="ref-history-row"><span class="mini-icon">${icon('chat')}</span><button data-action="open-chat" data-id="${esc(c.id)}"><b>${esc(c.title)}</b><small>${new Date(c.updated).toLocaleString()} · ${c.messages.length} messages</small></button><button class="icon-button danger" data-action="delete-chat" data-id="${esc(c.id)}" aria-label="Delete conversation">${icon('trash')}</button></article>`).join(''):`<div class="ref-empty"><span class="feature-icon">${icon('chat')}</span><h2>${historySearch?'No matching conversations':'Your history starts here'}</h2><p>${historySearch?'Try another search.':'Conversations are saved on this device.'}</p><a class="primary" href="#assistant">Start a conversation ${icon('arrow')}</a></div>`}</section>`;
}
function refDocuments() {
  const examples=[['CloudCore_Enterprise_Proposal.pdf','PDF','4.2 MB'],['Network_Strategy.docx','Document','2.4 MB'],['Infrastructure_Plan.pptx','Presentation','3.1 MB']];
  return `<section class="ref-document-heading"><div><h1>Document Insights</h1><p>Understand. Compare. Extract.</p></div><span class="ref-document-symbol">${icon('file')}${icon('spark')}</span><span>Turn your documents<br>into actionable insights<br>with AI</span></section><section class="panel ref-document-upload"><div class="dropzone" data-drop="document"><span class="feature-icon">${icon('file')}</span><h3>${docFile?esc(docFile.name):'Upload a document'}</h3><p>${docFile?'Your document is ready to review':'Drag and drop or <button data-action="choose-document">click to upload</button>'}</p><small>PDF, DOCX, PPTX, TXT, XLSX (Max 50MB)</small><button class="primary" data-action="choose-document">${icon('upload')}${docFile?'Choose another document':'Upload Document'}${icon('arrow')}</button></div></section><section class="ref-document-actions">${[['file','Summarize','Get key takeaways instantly.'],['grid','Compare','Find differences and insights.'],['file','Extract','Pull key information.'],['chart','Analyze','Identify trends and risks.']].map(([i,t,d],n)=>`<button class="panel capability-${n}" data-action="document-action" data-title="${t} document"><span class="mini-icon">${icon(i)}</span><span><b>${t}</b><small>${d}</small></span><i class="ref-round-arrow">${icon('arrow')}</i></button>`).join('')}</section>${docFile?`<section class="panel ref-document-ready"><div class="panel-heading">${icon('spark')}<div><h2>${esc(docFile.name)}</h2><p>${esc(docJobStatus||'Selected on this device. Upload to the AI service to prepare it for questions.')}</p></div><button class="primary" data-action="ingest-document-ai" ${docIngesting?'disabled':''}>${docIngesting?'Uploading…':'Analyze document'}</button></div><div class="tabs" role="tablist" aria-label="Document analysis">${['Summary','Key Points','Actions'].map(t=>`<button role="tab" aria-selected="${docTab===t}" data-action="doc-tab" data-tab="${t}" class="${docTab===t?'active':''}">${t}</button>`).join('')}</div><p class="ref-analysis-note">${docTab==='Summary'?'Once indexed, ask CloudCore AI for a summary grounded in this document.':docTab==='Key Points'?'Ask the assistant to extract key points with references to your document.':'Ask the assistant to identify decisions, actions and open questions.'}</p><a class="outline" href="#assistant">Ask about this document ${icon('arrow')}</a></section>`:''}<section class="ref-recent-documents"><div class="ref-table-heading"><div><h2>Recent Documents</h2><p>${docFile?'Your selected document and example files.':'Example files — select a document to start your own analysis.'}</p></div><label class="ref-search">${icon('search')}<input id="ref-document-search" placeholder="Search documents..." aria-label="Search documents"></label></div><div class="panel ref-table-wrap"><table><thead><tr><th>Name</th><th>Type</th><th>Uploaded</th><th>Size</th><th>Key Insights</th><th>Status</th></tr></thead><tbody>${(docFile?[[docFile.name,docFile.name.split('.').pop().toUpperCase(),(docFile.size/1048576).toFixed(2)+' MB'],...examples]:examples).map(([n,t,s],i)=>`<tr data-document-name="${esc(n.toLowerCase())}"><td><span class="mini-icon">${icon('file')}</span><b>${esc(n)}</b></td><td><span class="ref-type">${esc(t)}</span></td><td>${docFile&&i===0?'Just selected':'Example file'}</td><td>${s}</td><td>${docFile&&i===0?'Ready to analyze':'Preview available'}</td><td><button class="soft-button" data-action="${docFile&&i===0?'full-analysis':'ref-example-document'}">${docFile&&i===0?'Selected':'View example'}${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div></section>`;
}
function refImages() {
  const examples=[['tower','Telecom Tower','Identify equipment and infrastructure','assets/example-tower.svg'],['map','Satellite Map','Analyze locations and land use','assets/example-map.svg'],['datacenter','Data Center','Identify assets and infrastructure','assets/example-datacenter.svg'],['diagram','Diagram','Extract text and understand diagrams','assets/diagram.svg']];
  return `<div class="ref-page-heading"><h1>Image Analysis</h1><p>Upload an image to analyze, extract information or get insights.</p></div><section class="ref-image-upload"><div class="tabs image-tabs" role="tablist" aria-label="Image source"><button role="tab" aria-selected="${imageMode==='upload'}" class="${imageMode==='upload'?'active':''}" data-action="image-mode" data-mode="upload">Upload Image</button><button role="tab" aria-selected="${imageMode==='url'}" class="${imageMode==='url'?'active':''}" data-action="image-mode" data-mode="url">Analyze from URL</button></div>${imageMode==='upload'?`<div class="dropzone" data-drop="image">${icon('image')}<h3>Drag and drop an image here</h3><p>or <button data-action="choose-image">click to upload</button></p><small>JPG, PNG, WEBP (Max 20MB)</small><button class="primary" data-action="choose-image">${icon('upload')}Upload Image</button></div>`:`<form id="url-form" class="ref-url-form"><label for="ref-image-url">Direct HTTPS image URL</label><input id="ref-image-url" name="url" type="url" required placeholder="https://example.com/image.jpg"><button class="primary" type="submit">Load image ${icon('arrow')}</button></form>`}</section><div class="ref-example-heading"><h2>Try an example</h2><small>Illustrative previews</small></div><section class="ref-image-examples">${examples.map(([id,t,d,src])=>`<button data-action="example-image" data-example="${id}"><img src="${src}" alt="${t} example"><span><b>${t}</b><small>${d}</small></span></button>`).join('')}</section><section class="panel ref-image-results"><div class="panel-heading"><div><h2>Analysis Results</h2><p>AI-powered analysis with detailed insights and extracted information.</p></div>${imageURL?`<button class="outline" data-action="ref-view-image">${icon('image')}View Full Image</button><button class="primary" data-action="analyze-image-ai" ${visionLoading?'disabled':''}>${icon('spark')}${visionLoading?'Analyzing…':'Analyze Image'}</button>`:''}</div>${imageURL?`<div class="ref-vision-layout"><img class="ref-vision-preview" src="${esc(imageURL)}" alt="Selected image for analysis"><div class="ref-vision-content"><h3>${icon('image')}Overview</h3>${visionResult?`<div class="vision-result-card">${renderMarkdown(visionResult)}</div>`:'<p>Your image is ready. Select Analyze Image to generate observations and extract visible text.</p>'}<div class="ref-vision-reminder">${icon('shield')}Review AI observations before making decisions.</div>${visionResult?'<button class="outline" data-action="clear-vision">Clear result</button>':''}</div></div>`:`<div class="ref-vision-placeholder"><span class="feature-icon">${icon('image')}</span><h3>Select an image to see its analysis</h3><p>Preview equipment, maps and diagrams, or upload your own image.</p></div>`}</section>`;
}
function refLaunchForm() {
  return `<div class="meeting-card-heading"><span class="feature-icon">${icon('video')}</span><div><h2>Join a Teams meeting</h2><p>The organizer must admit the bot from the lobby.</p></div></div><form id="meeting-form"><label class="meeting-url"><span>Microsoft Teams link</span><input name="meetingUrl" type="text" inputmode="url" required placeholder="https://teams.microsoft.com/meet/..."></label><div class="bot-identity"><span>${icon('chip')}</span><div><small>BOT DISPLAY NAME</small><b>PTCL AI NOTETAKER</b></div></div><label class="consent-check"><input name="consent" type="checkbox" required><span>I confirm that participants will be informed and recording is permitted for this meeting.</span></label>${meetingsError?`<p class="meeting-error">${esc(meetingsError)}</p>`:''}<button class="primary" type="submit" ${meetingsLoading?'disabled':''}>${icon('video')}${meetingsLoading?'Starting bot…':'Join meeting now'}</button></form><p class="ref-capacity">${meetingsState.capacity.active} of ${meetingsState.capacity.maximum} meeting slots active</p>`;
}
function refMeetings() {
  if(selectedMeetingId)return meetingDetailView();
  const list=meetingsState.meetings||[],m=meetingsState.preview||list[0];
  return `<div class="ref-meetings-heading"><div><h1>Meeting Intelligence</h1><p>Capture. Understand. Act.</p></div><button class="primary" data-action="ref-new-meeting">${icon('plus')}New Meeting</button></div><div class="ref-meetings-layout"><section><div class="ref-meeting-filters"><b>All Meetings</b><a href="#history">My conversations</a></div><section class="panel ref-meeting-list"><label class="ref-search">${icon('search')}<input id="ref-meeting-search" placeholder="Search meetings..." aria-label="Search meetings"></label><div class="meeting-list">${list.length?list.map(meetingRowView).join(''):`<div class="ref-empty"><span class="feature-icon">${icon('video')}</span><h2>${meetingsLoading?'Loading meetings…':'No meetings yet'}</h2><p>Recorded Teams meetings and their summaries will appear here.</p></div>`}</div><button class="outline" data-action="refresh-meetings">${icon('history')}Refresh meetings</button></section></section><section class="panel ref-meeting-preview">${m?refMeetingPreview(m):`<div class="ref-meeting-cover"></div>${refLaunchForm()}`}</section></div>`;
}
function refMeetingPreview(m) {
  const mom=m.mom,topics=mom?.topics||[],actions=mom?.actionItems||[];
  return `<div class="ref-meeting-cover"></div><h2>${esc(m.title||'Microsoft Teams meeting')}</h2><div class="ref-meeting-meta"><span>${icon('clock')}${new Date(m.createdAt).toLocaleString()}</span><span class="meeting-status ${esc(m.status)}">${esc(statusText(m.status))}</span></div><div class="ref-meeting-preview-actions"><span>${(m.participants||[]).length} participants</span><button class="primary" data-action="open-meeting" data-id="${esc(m.id)}">${icon('file')}View meeting</button></div><div class="tabs"><span class="active">Summary</span><span>Action Items</span><span>Transcript</span></div><h3>${icon('bulb')}Key Discussion Points</h3>${topics.length?`<ol class="ref-discussion-points">${topics.slice(0,4).map(t=>`<li><b>${esc(t.title)}</b><p>${esc(t.notes)}</p></li>`).join('')}</ol>`:`<p class="ref-analysis-note">${mom?esc(mom.summary):'Open this meeting to see its transcript, recording and meeting minutes.'}</p>`}<h3>${icon('check')}Action Items</h3>${actions.length?actions.slice(0,4).map(a=>`<div class="ref-preview-action">${icon('check')}<span>${esc(a.task)}</span><small>${esc(a.owner||'Unassigned')}</small></div>`).join(''):'<p class="ref-analysis-note">Action items appear after meeting minutes have been generated.</p>'}`;
}
function refSettings() {
  const u=appUser||{};
  return `<div class="ref-page-heading"><h1>Settings</h1><p>Manage your account, preferences, and workspace.</p></div><nav class="ref-settings-tabs" aria-label="Settings sections"><button class="active" data-action="ref-settings-account">${icon('user')}Account</button><button data-action="ref-preferences">${icon('sliders')}Preferences</button><button data-action="ref-security">${icon('shield')}Security</button><button data-action="ref-integrations">${icon('link')}Integrations</button></nav><section class="panel ref-profile-panel"><div class="panel-heading"><span class="feature-icon">${icon('settings')}</span><div><h2>Profile</h2><p>Your personal information and role in CloudCore AI workspace.</p></div><button class="soft-button" data-action="profile">${icon('user')}View Profile</button></div><div class="ref-profile-identity"><span class="avatar">${esc((u.displayName||'U')[0])}</span><div><h2>${esc(u.displayName||'CloudCore user')}</h2><p>PTCL Smart Cloud</p></div></div><div class="ref-profile-fields">${[['Name',u.displayName],['Username',u.username],['Email',u.email||'Not provided'],['Role',u.role],['Workspace','CloudCore AI'],['Language','English']].map(([l,v])=>`<label><span>${l}</span><input readonly value="${esc(v||'Not provided')}" aria-label="${l}"></label>`).join('')}</div></section><section class="panel ref-workspace-details"><div class="panel-heading"><span class="feature-icon">${icon('building')}</span><div><h2>Workspace Details</h2><p>Information about your current workspace.</p></div></div><div class="ref-profile-fields"><label><span>Workspace Name</span><input readonly value="CloudCore AI Workspace"></label><label><span>Meeting Capacity</span><input readonly value="${meetingsState.capacity.maximum} concurrent meetings"></label><label><span>Account</span><input readonly value="${esc(u.username||u.displayName||'Workspace member')}"></label><label><span>Access</span><input readonly value="${esc(u.role||'Member')}"></label></div>${['dev','admin'].includes(u.role)?'<button class="outline" data-action="ref-users">'+icon('users')+' Manage workspace users</button>':''}</section>`;
}
function refHandleAction(a,el) {
  if(a==='ref-new-meeting'){modal(refLaunchForm());bind();return true;}
  if(a==='ref-document-route'){location.hash='documents';return true;}
  if(a==='ref-example-document'){modal(`<h2>Example document analysis</h2><span class="example-label">EXAMPLE ANALYSIS</span><div class="tabs" role="tablist" aria-label="Document analysis">${['Summary','Key Points','Actions'].map(t=>`<button role="tab" aria-selected="${docTab===t}" data-action="ref-example-tab" data-tab="${t}" class="${docTab===t?'active':''}">${t}</button>`).join('')}</div><p>${docTab==='Summary'?sampleSummary:docTab==='Key Points'?'Enterprise connectivity, cloud deployment options and managed support.':'Review deployment requirements, compare connectivity options and confirm service expectations.'}</p>`);return true;}
  if(a==='ref-example-tab'){docTab=el.dataset.tab;refHandleAction('ref-example-document',el);return true;}
  if(a==='ref-view-image'){modal(`<h2>Selected image</h2><img class="ref-full-image" src="${esc(imageURL)}" alt="Selected image">`);return true;}
  if(a==='ref-settings-account'){route();return true;}
  if(a==='ref-security'){openSettingsModal('profile');return true;}
  if(a==='ref-users'){openSettingsModal('users');return true;}
  if(a==='ref-preferences'){modal('<h2>Preferences</h2><p>Your workspace follows this device’s accessibility preferences, including reduced motion. Conversations are saved locally on this device.</p>');return true;}
  if(a==='ref-integrations'){modal('<h2>Workspace integrations</h2><p>Teams meetings, document analysis and image analysis use the services configured by your workspace administrator.</p><a class="outline" href="#meetings">Open Meeting Intelligence</a>');return true;}
  return false;
}
function refBind() {
  const search=$('#ref-document-search');if(search)search.oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('[data-document-name]').forEach(row=>row.hidden=!row.dataset.documentName.includes(q));};
  const meetingsSearch=$('#ref-meeting-search');if(meetingsSearch)meetingsSearch.oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.meeting-row').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q));};
}
